package com.brightloop.subscription;
import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.time.LocalDate;import java.util.List;
public final class SubscriptionDtos{private SubscriptionDtos(){}public record Request(@NotNull Long customerId,@NotNull Long planId,Long variantId,@NotNull LocalDate startDate,LocalDate expiryDate,@Min(1) int quantity,String paymentTerms,String discountCode){}public record Line(Long id,Long productId,String productName,Long variantId,String description,int quantity,BigDecimal unitPrice,BigDecimal taxRate){static Line of(SubscriptionLine l){return new Line(l.getId(),l.getProduct().getId(),l.getProduct().getName(),l.getVariant()==null?null:l.getVariant().getId(),l.getDescription(),l.getQuantity(),l.getUnitPrice(),l.getTaxRate());}}public record Response(Long id,String subscriptionNumber,Long customerId,String customerName,String customerEmail,Long planId,String planName,LocalDate startDate,LocalDate expiryDate,String billingFrequency,String paymentTerms,String status,int quantity,BigDecimal unitPrice,BigDecimal subtotal,BigDecimal taxAmount,BigDecimal discountAmount,BigDecimal grandTotal,LocalDate nextBillingDate,List<Line> lines){static Response of(Subscription s){return new Response(s.getId(),s.getSubscriptionNumber(),s.getCustomer().getId(),s.getCustomer().getFullName(),s.getCustomer().getEmail(),s.getPlan().getId(),s.getPlan().getName(),s.getStartDate(),s.getExpiryDate(),s.getBillingFrequency().name(),s.getPaymentTerms(),s.getStatus(),s.getQuantity(),s.getUnitPrice(),s.getSubtotal(),s.getTaxAmount(),s.getDiscountAmount(),s.getGrandTotal(),s.getNextBillingDate(),s.getLines().stream().map(Line::of).toList());}}}
